 public static function unavailableDurability():array {return [['0','0','0','REPEATABLE-READ'],['2','0','0','REPEATABLE-READ'],['1','1','0','REPEATABLE-READ'],['1','0','0','READ-COMMITTED']];}
 /** @dataProvider unavailableDurability */
 public function testUnavailableCommitDurabilityFailsBeforeSourceAdmission(string $flush,string $binlog,string $sync,string $isolation):void {
  $this->install();[$scope]=$this->product();DigiForge\Core\Settings::protectProduction();global $wpdb;$calls=0;$filter=static function($q)use($flush,$binlog,$sync,$isolation,&$calls,$wpdb){if(str_contains($q,'@@innodb_flush_log_at_trx_commit AS flush_commit')){++$calls;return $wpdb->prepare('SELECT %s AS flush_commit,%s AS binlog,%s AS sync_binlog,%s AS isolation_level',$flush,$binlog,$sync,$isolation);}return $q;};add_filter('query',$filter);try{$r=(new NativeBusinessVersionRepository())->readCurrent($scope,1,1,str_repeat('f',64),1,[],'none');self::assertWPError($r);self::assertSame('native_business_version_durability_unavailable',$r->get_error_code());self::assertFalse($r->get_error_data()['retry_permitted']);self::assertSame(1,$calls);}finally{remove_filter('query',$filter);}self::assertSame('0',(string)$wpdb->get_var('SELECT COUNT(*) FROM '.NativeBusinessVersionSchema::table()));
 }

 public function testMissingDownstreamPolicyCapabilityDeniesBeforeVersionStorage():void {
  [$s]=$this->product();DigiForge\Core\Settings::protectProduction();$user=wp_get_current_user();$original=$user->caps['manage_digiforge']??null;$user->add_cap('manage_digiforge',false);$reads=0;$trap=static function($q)use(&$reads){if(str_contains($q,NativeBusinessVersionSchema::table()))++$reads;return $q;};add_filter('query',$trap);try{$repo=new NativeBusinessVersionRepository();self::assertWPError($repo->readCurrent($s,1,1,str_repeat('f',64),1,[],'none'));self::assertWPError($repo->recordReviewedVersion($s,1,1,str_repeat('f',64),1,[],'none',0,self::ZERO));self::assertSame(0,$reads);}finally{remove_filter('query',$trap);if($original===null)$user->remove_cap('manage_digiforge');else $user->add_cap('manage_digiforge',$original);}
